// Links a room to the university's 3D campus map (map.uni-kassel.de, by mapongo). The map opens a
// building at one floor, ?p=1&b=<building>&f=<floor>, and marks a room with &l=<room>. Rooms the map
// has are in map-rooms.js (generated by scraper/map-rooms.js); other rooms open their building at the
// floor their number starts with ("-1139" is the basement, "0401" the ground floor).
//
// The link itself opens the campus view with the room's building marked (MAP_CAMPUS), so the building
// is seen among the others first; the building's floor buttons and the map's search lead to the room.
//
// eCampus names buildings by address, the map by name. The address to building number pairs come from
// the university's own staff lists (AL147 Brandschutzhelfer and Ersthelfende lists, Rev6: "Arnold-Bode-Str.
// 10 / Wiso C 7220"); the map's model files carry the same numbers (7220_0.dae is a floor of Wiso C).
// Buildings without such evidence open their campus instead, so a link never shows a wrong building.
// Map ids are from map.uni-kassel.de/api/project/1/buildings and /floors (October 2026).

import { MAP_CAMPUS, MAP_ROOMS } from './map-rooms.js';

const MAP_URL = 'https://map.uni-kassel.de/';

const CAMPUS = {
  hopla: { b: 5, f: 21 },
  hps: { b: 15, f: 59 },
  wa: { b: 59, f: 151 },
  witzenhausen: { b: 57, f: 149 },
  kunsthochschule: { b: 69, f: 161 },
  sport: { b: 65, f: 163 },
};

// Map buildings: floor ids by floor number. Rooms on a floor the map lacks open the ground floor.
const B = {
  campusCenter: { b: 1, floors: { 0: 7, '-1': 9, 1: 5, 2: 3, 3: 1 } }, // CC, Moritzstraße 18 (7280)
  avz1: { b: 7, floors: { 0: 23, 1: 25, 2: 27, 3: 29 } }, // AVZ I (1010)
  k10: { b: 17, floors: { 0: 61, 1: 63 } }, // Henschelstraße 2 / K10 (7030)
  ing3: { b: 19, floors: { 0: 65, 1: 67, 2: 69, 3: 71 } }, // Mönchebergstr. 7 (7090)
  wisoA: { b: 29, floors: { 0: 87, 1: 89 } }, // Nora-Platiel-Str. 4 / Wiso A (7200)
  studWohnenA: { b: 31, floors: { 0: 91 } }, // Nora-Platiel-Str. 8-10 (Stud. Wohnen) (7205)
  wisoB: { b: 33, floors: { 0: 93, 1: 95 } }, // Nora-Platiel-Str. 1 and 5 / Wiso B (7210)
  wisoC: { b: 37, floors: { 0: 99, 1: 101 } }, // Arnold-Bode-Str. 10 / Wiso C (7220)
  ing1: { b: 47, floors: { 0: 117, 1: 119, 2: 121 } }, // Kurt-Wolters-Str. 3 (7320)
  asl1: { b: 49, floors: { 0: 123 } }, // Universitätsplatz 9 / ASL 1 (7670)
  gkw: { b: 51, floors: { 0: 125, 1: 127 } }, // Kurt-Wolters-Str. 5 (7710)
  musik: { b: 53, floors: { 0: 129, 1: 131, 2: 133, 3: 135, 4: 137 } }, // Mönchebergstraße 1 (7720)
  wizSchule: { b: 71, floors: { 0: 157, '-1': 245, 1: 159 } }, // WIZ Ehem. Schulgebäude (3060)
  wizNbs: { b: 73, floors: { 0: 165, 1: 249, 2: 251 } }, // WIZ Hörsaal- und Laborgebäude / NBS (3190)
  wa71: { b: 75, floors: { 0: 167, 1: 169, 2: 171, 3: 255 } }, // Wilhelmshöher Allee 71 (4100)
  emilien: { b: 81, floors: { 0: 185, '-1': 183, 1: 187 } }, // Emilienstr. 41 (4600)
  uk86: { b: 83, floors: { 0: 189, 1: 191, 2: 193 } }, // Untere Königsstr. 86 (7760)
  rosen: { b: 85, floors: { 0: 195, 1: 197, 2: 199 } }, // Kleine Rosenstr. 1-3 (7840)
  wizKloster: { b: 99, floors: { 0: 225, 1: 227, 2: 229 } }, // WIZ Ehem. Kloster (3020)
  wizSchachtel: { b: 101, floors: { 0: 231 } }, // WIZ Grüne Schachtel (3110)
  wizWohnheim: { b: 105, floors: { 0: 235, 1: 237 } }, // WIZ Ehem. Studentenwohnheim (by name)
  wizS: { b: 107, floors: { 0: 239, 1: 241, 2: 243 } }, // WIZ Hörsaal- und Laborgebäude / S (3030)
};

// eCampus building (the last bracket of a room name) to map building or campus.
// Not linked to a building, for want of evidence: Arnold-Bode 2, 8 and 12, Nora-Platiel 3, 6 and 9,
// G.-Forster-Str. 4, Möncheberg 3 (7310) and Diagonale (no model on the map), Moritzstr. 2, and
// WA 73 (three map buildings share that address). Henschelstraße 2 is K10 in the staff lists, but
// FB06 names K10 Gottschalkstr. 22 and Henschelstr. 2 the ASL-Neubau, so it opens the campus too.
const BUILDINGS = {
  'Moritzstr. 18 Campus Center': B.campusCenter,
  'AVZ I': B.avz1,
  'Möncheberg 7': B.ing3,
  'Nora-Platiel 4': B.wisoA,
  'Nora-Platiel 8': B.studWohnenA,
  'Nora-Platiel 1': B.wisoB,
  'Nora-Platiel 5': B.wisoB,
  'Arnold-Bode 10': B.wisoC,
  'Kurt-Wolters 3': B.ing1,
  'Universitätsplatz 9, ASL 1': B.asl1,
  'Kurt-Wolters 5': B.gkw,
  'Möncheberg 1': B.musik,
  'WIZ, ehem. Schulgebäude': B.wizSchule,
  'WIZ, Hörsaal-u.Laborgebäude, Nbhfstr.': B.wizNbs,
  'WA-altes Gebäude (WA 71)': B.wa71,
  'WA-Neubau (Emilien)': B.emilien,
  'Untere Königsstraße 86': B.uk86,
  'Kleine Rosenstraße 1-3': B.rosen,
  'WIZ, ehem. Kloster': B.wizKloster,
  'WIZ, Grüne Schachtel': B.wizSchachtel,
  'WIZ, ehem. Studentenwohnheim': B.wizWohnheim,
  'WIZ, Hörsaal-u.Laborgebäude, Steinstr.': B.wizS,
  'WA-altes Gebäude (WA 73)': CAMPUS.wa,
  'Wilhelmshöher Allee': CAMPUS.wa,
  'WIZ, Nordbahnhofstr.': CAMPUS.witzenhausen,
  'Heinr.-Plett-Str.': CAMPUS.hps,
  'Menzelstraße 15 Südbau': CAMPUS.kunsthochschule,
  'Damaschkestraße 25': CAMPUS.sport,
};
// Department rooms that eCampus names without a building ("Raum 0303c im Fachgebiet", from a remark):
// [map building, floor, room], for rooms whose department and map room agree.
// 0303c: IES (Prof. Sick) is at Wilhelmshöher Allee 73 (IES contact page, office 0307b), and the map has
// Raum 0303C only in WA 73 (Teil 3).
const DEPARTMENT_ROOMS = { '0303c': [77, 175, 31215] };
const HOPLA = /^(?:Arnold-Bode|Nora-Platiel|G\.-Forster-Str\.|Möncheberg|Moritzstr\.|Diagonale|Gottschalk|Henschelstraße) \d/;

// The building (last bracket) and room number of an eCampus room name: "Raum 1120 A (Kurt-Wolters 3)" is
// Kurt-Wolters 3, 1120a; "Hörsaal 1 (Raum -1139) (…)" is -1139; "Hörsaal 0425 (…)" is 0425.
export function roomParts(room) {
  const building = /\(([^()]*(?:\([^()]*\))?[^()]*)\)\s*$/.exec(room ?? '')?.[1]?.trim();
  const number = /\b(?:Raum|Hörsaal|Labor)\s+(-?\d{4}(?:\s?[a-zA-Z]\b)?)(?!\d)/.exec(room ?? '')?.[1];
  return { building, number: number?.replace(/\s/g, '').toLowerCase() };
}

// A room number starts with its floor: -1139 is on -1, 0401 on 0, 2004 on 2.
export const floorOf = (number) => (number ? Number(/^-?\d/.exec(number)[0]) : null);

// The map building of an eCampus building ({ b, floors }), or its campus ({ b, f }), or null.
export function buildingPlace(building) {
  return BUILDINGS[building] ?? (HOPLA.test(building ?? '') ? CAMPUS.hopla : null);
}

// Where a room is on the map: { b, f } (map building and floor), with l (the room) when the map has it,
// or null for rooms the map does not have.
export function mapPlace(room) {
  const { building, number } = roomParts(room);
  if (!building) {
    const known = /\bim Fachgebiet\b/.test(room) && DEPARTMENT_ROOMS[number];
    return known ? { b: known[0], f: known[1], l: known[2] } : null;
  }
  const known = number && MAP_ROOMS[`${building}|${number}`];
  if (known) return { b: known[0], f: known[1], l: known[2] };
  const place = buildingPlace(building);
  if (!place?.floors) return place;
  return { b: place.b, f: place.floors[floorOf(number)] ?? place.floors[0] };
}

// Where a room's link opens: its building marked on the campus view ({ b, f, l, building: true }),
// or, for a building the campus view does not mark, the place mapPlace() gives.
export function linkPlace(room) {
  const place = mapPlace(room);
  const spot = place && MAP_CAMPUS[place.b];
  return spot ? { b: spot[0], f: spot[1], l: spot[2], building: true } : place;
}

// Map link for a room, in German or English (the map has no other language).
export function mapUrl(room, lang) {
  const place = linkPlace(room);
  return place && `${MAP_URL}?p=1&b=${place.b}&f=${place.f}${place.l ? `&l=${place.l}` : ''}&lang=${lang === 'de' ? 'de' : 'en'}`;
}
